const trac_pidz: i32 = if (builtin.os.tag != .windows) (if (chil.id) |pidz| @intCast(pidz) else 0) else 0;
if (trac_pidz > 0) orphTrac(allo, iozz, trac_pidz); defer if (trac_pidz > 0) orphUntr(allo, iozz, trac_pidz);
var regi_chil: ?*std.process.Child = null; var jobz_owne = false;
if (opts.jobz_iden.len > 0) { if (regz.gpaz.create(std.process.Child)) |boxz| { boxz.* = chil; regi_chil = boxz; if (regz.addz(iozz, opts.jobz_iden, .{ .chil = boxz, .jobz = jobz, .ring = opts.ring })) |_| { jobz_owne = true; } else |_| { regz.gpaz.destroy(boxz); regi_chil = null; } } else |_| {} }
