var moni: ?std.Thread = null;
if (opts.time_msec > 0 or opts.hear_msec > 0) { moni = std.Thread.spawn(.{ .stack_size = CF.auxi_stak }, moniMain, .{&stat}) catch null; stat.hasz_moni = moni != null; }
if (proc.stdout) |outz_file| { if (proc.stderr) |errz_file| { if (std.Thread.spawn(.{ .stack_size = CF.auxi_stak }, draiMain, .{ &stat, errz_file, "err" })) |thre| { draiMain(&stat, outz_file, "out"); thre.join(); } else |_| { stat.note("err", "auto-task: no thread for stderr — command stopped\n"); var entr = regi.Entr{ .chil = proc, .jobz = jobz }; regi.entrKill(&entr); draiMain(&stat, outz_file, "out"); draiMain(&stat, errz_file, "err"); } } else draiMain(&stat, outz_file, "out"); }
